#requires -Version 5.1
[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$RunId,[string]$ToolkitRoot=(Split-Path -Parent $PSScriptRoot))
$env:TZ='UTC'
$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'Toolkit.Core.psm1') -Force
$runRoot=Join-Path (Join-Path $ToolkitRoot 'work') $RunId
if($RunId -cnotmatch '\Arun-[a-f0-9]{32}\z' -or [Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT){throw 'Windows adapter requires a validated Windows run.'}
$null=Test-ToolkitLedger -RunId $RunId -ToolkitRoot $ToolkitRoot
$ledger=Get-ToolkitLedger -RunId $RunId -ToolkitRoot $ToolkitRoot
if($ledger.run.mode -cne 'real' -or $ledger.run.platform -cne 'windows'){throw 'Fictional runs never collect actual host inventory.'}
$null=Test-ToolkitLedger -RunId $RunId -ToolkitRoot $ToolkitRoot
$stamp=[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssZ');$result=[ordered]@{schema_version='1.0';adapter='windows-selected-public-metadata';status='partial';observed_utc=[DateTime]::UtcNow.ToString('o');uninstall=@();appx=@();os=@();display_drivers=@();command_locations=@();coverage=@();errors=@();software_or_system_changes=$false;browser_or_private_data_read=$false;win32_product_used=$false;binary_version_commands_executed=$false}
try{
 foreach($spec in @(@('LocalMachine','Registry64','machine64'),@('LocalMachine','Registry32','machine32'),@('CurrentUser','Registry64','current-user'))){$base=$null;$key=$null;try{$hive=[Enum]::Parse([Microsoft.Win32.RegistryHive],$spec[0]);$view=[Enum]::Parse([Microsoft.Win32.RegistryView],$spec[1]);$base=[Microsoft.Win32.RegistryKey]::OpenBaseKey($hive,$view);$key=$base.OpenSubKey('SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',$false);if($key){foreach($name in $key.GetSubKeyNames()){if($result.uninstall.Count -ge 5000){throw 'Selected uninstall record cap reached.'};$sub=$null;try{$sub=$key.OpenSubKey($name,$false);if($sub){$display=[string]$sub.GetValue('DisplayName',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);if($display){$result.uninstall+=@([ordered]@{name=$display;version=[string]$sub.GetValue('DisplayVersion',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);publisher=[string]$sub.GetValue('Publisher',$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);scope=$spec[2]})}}}finally{if($sub){$sub.Dispose()}}}};$result.coverage+=@([ordered]@{scope=('selected uninstall '+$spec[2]);state='observed';limits='Three display values only. Uninstall strings, install paths, licences and full registry exports excluded.'})}catch{$result.errors+=@([ordered]@{scope=$spec[2];error_type=$_.Exception.GetType().Name})}finally{if($key){$key.Dispose()};if($base){$base.Dispose()}}}
 if(Get-Command Get-AppxPackage -ErrorAction SilentlyContinue){try{$result.appx=@(Get-AppxPackage -ErrorAction Stop|Select-Object Name,Version,Architecture,Publisher,SignatureKind,Status);$result.coverage+=@([ordered]@{scope='current-user Appx registrations';state='observed';limits='Registration metadata/health is not latest-offer or security clearance; no other-user/profile/package-body read.'})}catch{$result.errors+=@([ordered]@{scope='current-user Appx';error_type=$_.Exception.GetType().Name})}}else{$result.coverage+=@([ordered]@{scope='current-user Appx';state='not_checked';limits='Required command unavailable; no installation attempted.'})}
 if(Get-Command Get-CimInstance -ErrorAction SilentlyContinue){try{$result.os=@(Get-CimInstance -ClassName Win32_OperatingSystem -Property Caption,Version,BuildNumber,OSArchitecture|Select-Object Caption,Version,BuildNumber,OSArchitecture);$result.display_drivers=@(Get-CimInstance -ClassName Win32_PnPSignedDriver -Filter "DeviceClass='DISPLAY'" -Property DeviceName,DriverVersion,DriverDate,IsSigned,DriverProviderName|Select-Object DeviceName,DriverVersion,DriverDate,IsSigned,DriverProviderName);$result.coverage+=@([ordered]@{scope='selected OS/DISPLAY metadata';state='observed';limits='No serials, UUIDs, device identifiers, process command lines, services or firmware scan.'})}catch{$result.errors+=@([ordered]@{scope='OS/DISPLAY selected metadata';error_type=$_.Exception.GetType().Name})}}
 foreach($name in @('git','node','npm','python','py','pwsh')){$result.command_locations+=@(Get-Command -Name $name -CommandType Application -All -ErrorAction SilentlyContinue|Select-Object -First 8 Name,Source,CommandType)}
 $result.coverage+=@([ordered]@{scope='selected command resolution';state='observed';limits='Locations only; binaries not invoked and configuration/profile/environment values not dumped.'})
 $result.status=if($result.errors.Count){'partial'}else{'selected_metadata_collected'}
}catch{$result.errors+=@([ordered]@{scope='adapter';error_type=$_.Exception.GetType().Name});$result.status='partial_or_failed'}
Write-ToolkitArtifact -RunId $RunId -RelativePath ('evidence/windows-baseline-'+$stamp+'.json') -Role evidence -Content ($result|ConvertTo-Json -Depth 20) -ToolkitRoot $ToolkitRoot
[pscustomobject]@{status=$result.status;run_id=$RunId;evidence_relative_path=('evidence/windows-baseline-'+$stamp+'.json');source_scope='selected public metadata, not comprehensive inventory';maintenance_executed=$false}